import json,os,glob,re,urllib.parse,collections,sqlite3,zlib
W=os.environ['W']; R=W+'/results/'
DB=sqlite3.connect('file:'+W+'/home/db/advisories.sqlite?mode=ro&immutable=1',uri=True)
def ids_for(f):
 ids=[f['id']]+f.get('related_ids',[])+f['record'].get('aliases',[])
 if f['record']['id'].startswith('ALSA-'):
  r=json.loads(zlib.decompress(DB.execute('select json from records where id=?',(f['record']['id'],)).fetchone()[0]));ids+=r.get('related',[])
 return ids
def read(p): return json.load(open(p))
def key(p):
 p=urllib.parse.unquote(p.removeprefix('pkg:')); base,_,q=p.partition('?'); base=base.split('#')[0]; path,_,v=base.rpartition('@'); typ,_,name=path.partition('/'); quals=urllib.parse.parse_qs(q)
 if quals.get('epoch',['0'])[0]!='0' and ':' not in v: v=quals['epoch'][0]+':'+v
 v=re.sub(r'^0:','',v)
 if typ=='rpm':
  for a,b in [('rhel/','redhat/'),('rockylinux/','rocky/'),('alma/','almalinux/')]:
   if name.startswith(a): name=b+name[len(a):]
 if typ=='pypi': name=re.sub(r'[-_.]+','-',name).lower()
 return typ+'/'+name+'@'+v

def cves(ids): return sorted(set(v for i in ids if i for v in re.findall(r'(?<![A-Za-z0-9])CVE-\d{4}-\d{4,}',i)))
def add(m,k,ids,info):
 for c in cves(ids):
  pair=k+' | '+c
  m.setdefault(pair,[]).append(info)
def summarize_sets(a,b): return dict(a=len(a),b=len(b),common=len(a&b),a_only=sorted(a-b),b_only=sorted(b-a))
def load_image(x):
 k=x['key'];d=R+k+'/'
 t=read(d+'trivy.json');g=read(d+'grype.json');gc=read(d+'grype.cdx.json'); sb=read(glob.glob(d+'bscan/*.cdx.json')[0]);b=read(glob.glob(d+'bscan/*.findings.json')[0])
 inv={'bscan':{key(c['purl']) for c in sb.get('components',[]) if c.get('purl') and c.get('type') not in ['operating-system','file']},'trivy':{key(p['Identifier']['PURL']) for r in t.get('Results',[]) for p in r.get('Packages',[]) if p.get('Identifier',{}).get('PURL')},'grype':{key(c['purl']) for c in gc.get('components',[]) if c.get('purl') and c.get('type') not in ['operating-system','file']}}
 maps={tool:{} for tool in inv}
 for f in b['findings']:
  add(maps['bscan'],key(f['subject']['purl']),ids_for(f),dict(id=f['id'],record_id=f['record']['id'],severity=f['severity'],distro_severity=f.get('distro_severity',''),distro_status=f.get('distro_status',''),score=f.get('score'),fixed_in=f.get('fixed_in',[]),matched_by=f['matched_by'],release=f['subject'].get('release'),upstream=f['subject'].get('upstream'),affected=f.get('affected')))
 for r in t.get('Results',[]):
  pm={p['ID']:p for p in r.get('Packages',[])}
  for v in r.get('Vulnerabilities',[]):
   purl=v.get('PkgIdentifier',{}).get('PURL') or pm.get(v.get('PkgID'),{}).get('Identifier',{}).get('PURL')
   if not purl: raise Exception(v)
   add(maps['trivy'],key(purl),[v['VulnerabilityID']],dict(id=v['VulnerabilityID'],severity=v['Severity'],severity_source=v.get('SeveritySource'),fixed_in=v.get('FixedVersion'),status=v.get('Status'),source=v.get('DataSource'),url=v.get('PrimaryURL')))
 for m in g['matches']:
  v=m['vulnerability'];add(maps['grype'],key(m['artifact']['purl']),[v['id']]+[v['id'] for v in m.get('relatedVulnerabilities',[])],dict(id=v['id'],severity=v['severity'].upper(),fixed_in=v.get('fix'),source=v.get('dataSource'),namespace=v.get('namespace'),match_details=m.get('matchDetails')))
 out=dict(x,os=t['Metadata'].get('OS'),inventory={tool:sorted(vals) for tool,vals in inv.items()},inventory_comparison={},cves=maps,cve_comparison={},raw_findings={'bscan':len(b['findings']),'trivy':sum(len(r.get('Vulnerabilities',[])) for r in t.get('Results',[])),'grype':len(g['matches'])},bscan_subjects=b['subjects'],bscan_skipped=b['skipped'],bscan_histogram=b['by_severity'],bscan_db=b['db'])
 for a,bb in [('bscan','trivy'),('bscan','grype'),('trivy','grype')]:
  name=a+'_vs_'+bb; out['inventory_comparison'][name]=summarize_sets(inv[a],inv[bb]);out['cve_comparison'][name]=summarize_sets(set(maps[a]),set(maps[bb]))
  out['cve_comparison'][name]['severity_mismatches']=[dict(pair=p,a=sorted(set(v['severity'] for v in maps[a][p])),b=sorted(set(v['severity'] for v in maps[bb][p]))) for p in sorted(maps[a].keys() & maps[bb].keys()) if set(v['severity'] for v in maps[a][p])!=set(v['severity'] for v in maps[bb][p])]
 if os.path.exists(d+'exclude.json'):
  e=read(d+'exclude.json');out['exclude_histogram']=e['by_severity'];out['exclude_count']=len(e['findings']);out['excluded']=[dict(id=f['id'],purl=f['subject']['purl'],severity=f['severity'],distro_severity=f.get('distro_severity')) for f in b['findings'] if (f['id'],f['subject']['purl']) not in {(v['id'],v['subject']['purl']) for v in e['findings']}]
 return out
if __name__=='__main__':
 rows=[]
 for x in read(R+'images.json'):
  if not glob.glob(R+x['key']+'/bscan/*.findings.json'): continue
  row=load_image(x);rows.append(row)
  print(x['key'],'inv',[(k,len(v)) for k,v in row['inventory'].items()],'CVE',[(k,len(v)) for k,v in row['cves'].items()])
  for k,c in row['cve_comparison'].items(): print(k,c['common'],len(c['a_only']),len(c['b_only']),'severity',len(c['severity_mismatches']))
 json.dump(rows,open(R+'analysis.json','w'),ensure_ascii=False,indent=2)
